<?php
defined( 'ABSPATH' ) || exit;
final class SWC_Admin {
	public function hooks(){add_action('admin_menu',array($this,'menu'));add_action('admin_post_swc_admin_update',array($this,'update'));add_action('admin_post_swc_save_clinic_settings',array($this,'save_settings'));add_action('admin_notices',array($this,'notice'));}
	public function menu(){add_menu_page('Clinic Management','Clinic Management','manage_worldwide_clinic','clinic-management',array($this,'page'),'dashicons-calendar-alt',29);add_submenu_page('clinic-management','Appointments','Appointments','manage_worldwide_clinic','clinic-management',array($this,'page'));add_submenu_page('clinic-management','Clinic Settings','Clinic Settings','manage_worldwide_clinic','clinic-settings',array($this,'settings'));}
	public function page(){global $wpdb;$status=isset($_GET['status'])?sanitize_key(wp_unslash($_GET['status'])):'';$doctor=isset($_GET['doctor'])?absint($_GET['doctor']):0;$args=array('post_type'=>SWC_Helpers::TYPE,'post_status'=>'publish','posts_per_page'=>250,'orderby'=>'date','order'=>'DESC');$mq=array('relation'=>'AND');if($status&&isset(SWC_Helpers::statuses()[$status])){$mq[]=array('key'=>'_swc_status','value'=>$status);}if($doctor){$mq[]=array('key'=>'_swc_doctor_id','value'=>$doctor);}if(count($mq)>1){$args['meta_query']=$mq;}$items=get_posts($args);$doctors=SWC_Helpers::doctor_ids();?><div class="wrap swc-admin"><h1>Clinic Management</h1><p>Private scheduling information is visible only to authorized administrators, the selected doctor, and the patient.</p><form class="swc-admin-filter" method="get"><input type="hidden" name="page" value="clinic-management"><select name="status"><option value="">All statuses</option><?php foreach(SWC_Helpers::statuses() as $key=>$label):?><option value="<?php echo esc_attr($key);?>" <?php selected($status,$key);?>><?php echo esc_html($label);?></option><?php endforeach;?></select><select name="doctor"><option value="0">All doctors</option><?php foreach($doctors as $id):?><option value="<?php echo absint($id);?>" <?php selected($doctor,$id);?>><?php echo esc_html(get_the_author_meta('display_name',$id));?></option><?php endforeach;?></select><button class="button">Filter</button></form><table class="widefat striped"><thead><tr><th>Reference</th><th>Patient</th><th>Doctor</th><th>Requested time</th><th>Status</th><th>Management</th></tr></thead><tbody><?php if($items):foreach($items as $a):$id=$a->ID;$current=SWC_Helpers::status($id);?><tr><td>#<?php echo absint($id);?><br><small><?php echo esc_html(get_the_date('M j, Y',$id));?></small></td><td><?php echo esc_html(get_the_author_meta('display_name',$a->post_author));?><br><?php echo esc_html(SWC_Helpers::meta($id,'phone'));?></td><td><?php echo esc_html(get_the_author_meta('display_name',SWC_Helpers::meta($id,'doctor_id')));?></td><td><?php echo esc_html(SWC_Helpers::display_time(SWC_Helpers::meta($id,'preferred_at_utc'),'UTC'));?></td><td><?php echo esc_html(SWC_Helpers::statuses()[$current]);?></td><td><form action="<?php echo esc_url(admin_url('admin-post.php'));?>" method="post"><input type="hidden" name="action" value="swc_admin_update"><input type="hidden" name="appointment_id" value="<?php echo absint($id);?>"><?php wp_nonce_field('swc_admin_update_'.$id);?><select name="doctor_id"><?php foreach($doctors as $doctor_id):?><option value="<?php echo absint($doctor_id);?>" <?php selected(absint(SWC_Helpers::meta($id,'doctor_id')),$doctor_id);?>><?php echo esc_html(get_the_author_meta('display_name',$doctor_id));?></option><?php endforeach;?></select><select name="status"><?php foreach(SWC_Helpers::statuses() as $key=>$label):?><option value="<?php echo esc_attr($key);?>" <?php selected($current,$key);?>><?php echo esc_html($label);?></option><?php endforeach;?></select><input name="note" maxlength="500" placeholder="Internal audit note"><button class="button button-primary">Save</button></form></td></tr><?php endforeach;else:?><tr><td colspan="6">No appointments found.</td></tr><?php endif;?></tbody></table></div><?php }
	public function update(){$this->guard();$id=isset($_POST['appointment_id'])?absint($_POST['appointment_id']):0;check_admin_referer('swc_admin_update_'.$id);if(SWC_Helpers::TYPE!==get_post_type($id)){wp_die(esc_html__('Invalid appointment.','worldwide-clinic'),'',array('response'=>400));}$status=isset($_POST['status'])?sanitize_key(wp_unslash($_POST['status'])):'';$doctor=isset($_POST['doctor_id'])?absint($_POST['doctor_id']):0;if(!isset(SWC_Helpers::statuses()[$status])||!in_array($doctor,SWC_Helpers::doctor_ids(),true)){wp_die(esc_html__('Invalid appointment update.','worldwide-clinic'),'',array('response'=>400));}$note=isset($_POST['note'])?sanitize_text_field(wp_unslash($_POST['note'])):'';update_post_meta($id,'_swc_status',$status);update_post_meta($id,'_swc_doctor_id',$doctor);SWC_Helpers::audit($id,'admin-'.$status,$note);wp_safe_redirect(add_query_arg(array('page'=>'clinic-management','updated'=>'1'),admin_url('admin.php')));exit;}
	public function settings(){?><div class="wrap swc-admin"><h1>Clinic Settings</h1><form action="<?php echo esc_url(admin_url('admin-post.php'));?>" method="post"><input type="hidden" name="action" value="swc_save_clinic_settings"><?php wp_nonce_field('swc_save_clinic_settings');?><table class="form-table"><tr><th><label for="swc_phone">Clinic phone</label></th><td><input id="swc_phone" name="clinic_phone" value="<?php echo esc_attr(get_option('swc_clinic_phone',''));?>" placeholder="+12025550123"></td></tr><tr><th><label for="swc_whatsapp">Clinic WhatsApp</label></th><td><input id="swc_whatsapp" name="clinic_whatsapp" value="<?php echo esc_attr(get_option('swc_clinic_whatsapp',''));?>" placeholder="+12025550123"></td></tr><tr><th><label for="swc_emergency">Emergency notice</label></th><td><textarea id="swc_emergency" name="emergency_notice" rows="4" class="large-text"><?php echo esc_textarea(get_option('swc_emergency_notice','If you may be experiencing a medical emergency, contact your local emergency services immediately. Do not wait for an online appointment.'));?></textarea></td></tr></table><button class="button button-primary">Save Clinic Settings</button></form></div><?php }
	public function save_settings(){$this->guard();check_admin_referer('swc_save_clinic_settings');update_option('swc_clinic_phone',SWC_Helpers::phone(isset($_POST['clinic_phone'])?wp_unslash($_POST['clinic_phone']):''),false);update_option('swc_clinic_whatsapp',SWC_Helpers::phone(isset($_POST['clinic_whatsapp'])?wp_unslash($_POST['clinic_whatsapp']):''),false);update_option('swc_emergency_notice',isset($_POST['emergency_notice'])?sanitize_textarea_field(wp_unslash($_POST['emergency_notice'])):'',false);wp_safe_redirect(add_query_arg(array('page'=>'clinic-settings','updated'=>'1'),admin_url('admin.php')));exit;}
	private function guard(){if(!current_user_can('manage_worldwide_clinic')){wp_die(esc_html__('You are not allowed to manage the clinic.','worldwide-clinic'),'',array('response'=>403));}}
	public function notice(){if(current_user_can('activate_plugins')&&get_transient('swc_activation_notice')){delete_transient('swc_activation_notice');echo '<div class="notice notice-success is-dismissible"><p>Worldwide Clinic is active. Review Clinic Settings and doctor availability.</p></div>';}}
}

